package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec
var ledgerLines []string
var ledgerIdx int

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatZZ(value decimal.Decimal, pic string) string {
	// pic without sign, e.g. "ZZ,ZZ9.99" or "Z,ZZZ,ZZ9.99"
	// split at '.'
	dotIdx := strings.Index(pic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		decPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		decPic = ""
	}
	// count integer digit positions
	nInt := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			nInt++
		}
	}
	nDec := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			nDec++
		}
	}
	absVal := value.Abs()
	// integer part truncated toward zero
	intPart := absVal.Truncate(0)
	// decimal part: we need nDec digits, from absVal
	// Get fractional digits: (absVal - intPart) * 10^nDec
	// Use decimal arithmetic
	var decStr string
	if nDec > 0 {
		// scale absVal to nDec decimals truncating
		// absVal is at most 2 decimals, but be safe: truncate
		tmp := absVal.Truncate(int32(nDec))
		// fractional part
		frac := tmp.Sub(intPart)
		// shift
		shifted := frac.Shift(int32(nDec))
		// Should be integer
		// Use string formatting with zero pad
		// shifted may be negative? no abs
		s := shifted.Truncate(0).String()
		// remove sign, pad
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		// s may contain decimal point if not integer? but we truncated
		// ensure no dot
		if idx := strings.Index(s, "."); idx >= 0 {
			s = s[:idx]
		}
		// pad left zeros to nDec
		if len(s) < nDec {
			s = strings.Repeat("0", nDec-len(s)) + s
		} else if len(s) > nDec {
			s = s[len(s)-nDec:]
		}
		decStr = s
	}

	// integer digits mod 10^nInt
	var intDigits string
	if nInt > 0 {
		pow10 := decimal.NewFromInt(1).Shift(int32(nInt)) // 10^nInt
		// intPart may be large, mod
		mod := intPart.Mod(pow10)
		// mod is decimal, get string without dot
		s := mod.Truncate(0).String()
		if idx := strings.Index(s, "."); idx >= 0 {
			s = s[:idx]
		}
		if strings.HasPrefix(s, "-") {
			s = s[1:]
		}
		if s == "" {
			s = "0"
		}
		if len(s) < nInt {
			s = strings.Repeat("0", nInt-len(s)) + s
		} else if len(s) > nInt {
			s = s[len(s)-nInt:]
		}
		intDigits = s
	}

	// Build integer picture output
	var outInt strings.Builder
	idxDigit := 0
	suppressed := true
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := intDigits[idxDigit]
			idxDigit++
			if suppressed {
				if ch == 'Z' && d == '0' {
					outInt.WriteByte(' ')
					// stay suppressed
				} else {
					suppressed = false
					outInt.WriteByte(d)
				}
			} else {
				outInt.WriteByte(d)
			}
		} else if ch == ',' {
			if suppressed {
				outInt.WriteByte(' ')
			} else {
				outInt.WriteByte(',')
			}
		} else {
			outInt.WriteByte(byte(ch))
		}
	}
	result := outInt.String()
	if nDec > 0 {
		result += "." + decStr
	}
	return result
}

func formatSigned(value decimal.Decimal, picWithSign string) string {
	// picWithSign like "-Z,ZZZ,ZZ9.99" or "-ZZZ,ZZZ,ZZ9.99"
	signChar := ' '
	if value.Sign() < 0 {
		signChar = '-'
	}
	// remove leading '-'
	pic := picWithSign
	if len(pic) > 0 && pic[0] == '-' {
		pic = pic[1:]
	}
	body := formatZZ(value, pic)
	return string(signChar) + body
}

func formatUneditedInt(v int64, width int) string {
	s := fmt.Sprintf("%d", v)
	// keep low-order digits if overflow? For integer fields high-order dropped? Spec says storing keeps low-order. DISPLAY unedited numeric: print zero-padded to digit count, and if more digits than picture high-order dropped.
	if len(s) > width {
		// handle negative? not needed for WsSkipped (positive)
		s = s[len(s)-width:]
	}
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func mainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty (COBOL would error, but we follow)
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	ledgerLines = nil
	for scanner.Scan() {
		line := scanner.Text()
		// LINE SEQUENTIAL keeps content without newline; we will handle padding later
		ledgerLines = append(ledgerLines, line)
	}
	ledgerIdx = 0

	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	if WsFirstFlag != "Y" {
		acctBreakPara()
		branchBreakPara()
	}
	// CLOSE Ledger-File (deferred)
	grandPara()
}

func readPara() {
	if ledgerIdx >= len(ledgerLines) {
		WsEofFlag = "Y"
		return
	}
	raw := ledgerLines[ledgerIdx]
	ledgerIdx++
	// pad to 14 with spaces
	if len(raw) < 14 {
		raw = raw + strings.Repeat(" ", 14-len(raw))
	} else if len(raw) > 14 {
		raw = raw[:14]
	}
	// parse fields
	ledgerRec.BrBranch = raw[0:2]
	ledgerRec.BrAcct = raw[2:6]
	ledgerRec.BrType = raw[6:7]
	amtStr := raw[7:14]
	amtStr = strings.TrimSpace(amtStr)
	if amtStr == "" {
		ledgerRec.BrAmt = decimal.Zero
	} else {
		// digits only; may contain non-digit? assume digits
		// parse integer
		// remove any non-digit? keep digits
		clean := ""
		for _, ch := range amtStr {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			}
		}
		if clean == "" {
			ledgerRec.BrAmt = decimal.Zero
		} else {
			// parse as integer
			n, _ := decimal.NewFromString(clean)
			// shift -2 for V99
			ledgerRec.BrAmt = n.Shift(-2)
		}
	}
}

func processPara() {
	if WsFirstFlag == "Y" {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			acctBreakPara()
			branchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				acctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	postPara()
	readPara()
}

func postPara() {
	WsAmtEd = formatZZ(ledgerRec.BrAmt, "ZZ,ZZ9.99")
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Println(ledgerRec.BrAcct+" D "+WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Println(ledgerRec.BrAcct+" C "+WsAmtEd)
	default:
		WsSkipped++
		fmt.Println(ledgerRec.BrAcct + " ? SKIPPED")
	}
}

func acctBreakPara() {
	WsBalEd = formatSigned(WsBal, "-Z,ZZZ,ZZ9.99")
	fmt.Println("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.Zero
}

func branchBreakPara() {
	WsTotEd = formatSigned(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Println(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.Zero
}

func grandPara() {
	WsTotEd = formatSigned(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	fmt.Println("GRAND TOTAL:" + WsTotEd)
	fmt.Println("SKIPPED: " + formatUneditedInt(WsSkipped, 2))
}

func main() {
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = strings.Repeat(" ", 2)
	WsPrevAcct = strings.Repeat(" ", 4)
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0
	mainPara()
}
